// functional-groups.js
(()=>{'use strict';const {bank,info}=FUNCTIONAL_GROUPS,$=id=>document.getElementById(id),escape=s=>String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));let mode='identify',index=0,selection=null;const solved=new Set(),answers=new Map(),findOrder=[15,3,11,1,18,9,4,12,0,19,5,8,13,6,17,10,2,14,7,16],current=()=>bank[mode==='identify'?index:findOrder[index]],key=()=>mode+':'+current().id;
function members(q){return q.g.groups.find(g=>g.id===q.target);}
function grade(q,kind,value){const target=members(q);return kind==='identify'?value===target.type:value?.kind==='atom'?target.atoms.includes(value.id):value?.kind==='bond'?target.bonds.includes(value.id):value?.kind==='group'?value.id===target.id:false;}
function markup(q){const g=q.g,t=members(q),by=new Map(g.atoms.map(a=>[a.id,a])),all=g.atoms.flatMap(a=>[a.x]),ys=g.atoms.map(a=>a.y),cx=(Math.min(...all)+Math.max(...all))/2,cy=(Math.min(...ys)+Math.max(...ys))/2,hilite=mode==='identify'||solved.has(key()),parts=[];const trim=(a,b)=>{const d=Math.hypot(b.x-a.x,b.y-a.y),gapA=a.element==='C'?0:19,gapB=b.element==='C'?0:19,ux=(b.x-a.x)/d,uy=(b.y-a.y)/d;return{a:{x:a.x+gapA*ux,y:a.y+gapA*uy},b:{x:b.x-gapB*ux,y:b.y-gapB*uy},ux,uy};};
 const mark=hilite?t:selection&&mode==='find'?{type:'selection',atoms:selection.kind==='atom'?[selection.id]:g.bonds.filter(b=>b.id===selection.id).flatMap(b=>[b.a,b.b]),bonds:selection.kind==='bond'?[selection.id]:[]}:null;
 if(mark&&mark.type==='arene'){parts.push(`<polygon points="${mark.atoms.map(id=>{const a=by.get(id);return a.x+','+a.y}).join(' ')}" fill="none" stroke="#cce8ff" stroke-width="24" stroke-linejoin="round"/>`);}else if(mark){for(const b of g.bonds.filter(b=>mark.bonds.includes(b.id))){const a=by.get(b.a),z=by.get(b.b);parts.push(`<line x1="${a.x}" y1="${a.y}" x2="${z.x}" y2="${z.y}" stroke="#cce8ff" stroke-width="21" stroke-linecap="round"/>`);}for(const id of mark.atoms){const a=by.get(id),order=g.bonds.filter(b=>b.a===id||b.b===id).reduce((s,b)=>s+b.order,0),h=({O:2,N:3,S:2}[a.element]||1)-order,attached=g.bonds.find(b=>b.a===id||b.b===id),neighbour=attached?by.get(attached.a===id?attached.b:attached.a):null,left=neighbour&&neighbour.x>a.x+10;if(a.element!=='C'&&h>0){const extra=h>1?10:0,width=52+extra,centre=a.x+(left?-8:8);parts.push(`<rect data-label-highlight="${id}" x="${centre-width/2}" y="${a.y-22}" width="${width}" height="44" rx="20" fill="#cce8ff"/>`);}else parts.push(`<circle cx="${a.x}" cy="${a.y}" r="19" fill="#cce8ff"/>`);}}
 for(const b of g.bonds){const a=by.get(b.a),z=by.get(b.b),p=trim(a,z),ring=g.groups.find(r=>r.type==='arene'&&r.bonds.includes(b.id));let segments;if(ring&&b.order===2){const centre=ring.atoms.map(id=>by.get(id)).reduce((c,a)=>({x:c.x+a.x/ring.atoms.length,y:c.y+a.y/ring.atoms.length}),{x:0,y:0}),mid={x:(a.x+z.x)/2,y:(a.y+z.y)/2},side=((centre.x-mid.x)*(-p.uy)+(centre.y-mid.y)*p.ux)>0?1:-1,ox=-p.uy*8*side,oy=p.ux*8*side;segments=[{x1:a.x,y1:a.y,x2:z.x,y2:z.y},{x1:a.x+14*p.ux+ox,y1:a.y+14*p.uy+oy,x2:z.x-14*p.ux+ox,y2:z.y-14*p.uy+oy}];}else segments=(b.order===3?[-6,0,6]:b.order===2?[-4,4]:[0]).map(off=>({x1:p.a.x-off*p.uy,y1:p.a.y+off*p.ux,x2:p.b.x-off*p.uy,y2:p.b.y+off*p.ux}));for(const seg of segments)parts.push(`<line data-chemical-bond="${b.id}" x1="${seg.x1}" y1="${seg.y1}" x2="${seg.x2}" y2="${seg.y2}" stroke="#172532" stroke-width="2.4" stroke-linecap="round"/>`);}

 for(const a of g.atoms.filter(a=>a.element!=='C')){const order=g.bonds.filter(b=>b.a===a.id||b.b===a.id).reduce((s,b)=>s+b.order,0),h=({O:2,N:3,S:2}[a.element]||1)-order,attached=g.bonds.find(b=>b.a===a.id||b.b===a.id),neighbour=by.get(attached.a===a.id?attached.b:attached.a),left=neighbour.x>a.x+10;let label=escape(a.element);if(h>0)label=left?'H'+(h>1?`<tspan baseline-shift="sub" font-size="14">${h}</tspan>`:'')+label:label+'H'+(h>1?`<tspan baseline-shift="sub" font-size="14">${h}</tspan>`:'');parts.push(`<text x="${a.x+(h>0?(left?-8:8):0)}" y="${a.y}" text-anchor="middle" dominant-baseline="central" fill="#172532" font-size="22" font-family="Arial,sans-serif">${label}</text>`);}
 if(mode==='find'&&!solved.has(key())){for(const b of g.bonds){const a=by.get(b.a),z=by.get(b.b);parts.push(`<line data-fg-kind="bond" data-fg-id="${b.id}" role="button" tabindex="0" aria-label="Select bond ${+b.id.slice(1)+1}" x1="${a.x}" y1="${a.y}" x2="${z.x}" y2="${z.y}" class="fg-hit-bond"/>`);}for(const a of g.atoms)parts.push(`<circle data-fg-kind="atom" data-fg-id="${a.id}" role="button" tabindex="0" aria-label="Select ${a.element==='C'?'carbon':a.element} atom ${+a.id.slice(1)+1}" cx="${a.x}" cy="${a.y}" r="16" class="fg-hit-atom"/>`);}

 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${cx-380} ${cy-210} 760 420" role="group" aria-label="Bond-line molecule for question ${index+1}">${parts.join('')}</svg>`;}
function message(text,state='hint'){$('fg-feedback').textContent=text;$('fg-feedback').dataset.state=state;}
function begin(i=0){index=i;selection=null;const q=current(),target=members(q),done=solved.has(key());$('fg-count').textContent=`Question ${index+1} of 20`;$('fg-score').textContent=`Completed: ${[...solved].filter(x=>x.startsWith(mode+':')).length} / 20`;$('fg-progress').style.width=[...solved].filter(x=>x.startsWith(mode+':')).length*5+'%';$('fg-question').value=index;$('fg-prompt').textContent=mode==='identify'?'Name the highlighted functional group.':'Find the '+info[target.type][0].toLowerCase()+' group.';$('fg-instructions').textContent=mode==='identify'?'Use the complete highlighted group to decide its family.':'Click an atom or bond belonging to the requested group, then check your answer.';$('fg-answer-wrap').hidden=mode!=='identify';$('fg-answer').value=done?target.type:'';$('fg-answer').disabled=done;$('fg-board').innerHTML=markup(q);$('fg-check').disabled=done;$('fg-previous').disabled=index===0;$('fg-next').disabled=index===19;document.querySelectorAll('[data-fg-mode]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.fgMode===mode));const prior=answers.get(key());message(prior?.text||'Choose your answer, then select Check Answer.',prior?.state||'hint');}
function choose(next){mode=next;begin(0);}function check(){const q=current(),value=mode==='identify'?$('fg-answer').value:selection;if(!value){message(mode==='identify'?'Choose a functional group first.':'Select an atom or bond on the molecule first.');return false;}const correct=grade(q,mode,value),t=members(q),text=correct?'Correct. '+info[t.type][1]:mode==='identify'?'Not quite. Consider the entire highlighted group, including the atoms attached to any carbonyl.':'Not quite. That is outside the requested group. '+info[t.type][1];answers.set(key(),{text,state:correct?'correct':'incorrect'});if(correct){solved.add(key());begin(index);}else message(text,'incorrect');return correct;}
$('fg-question').innerHTML=bank.map((_,i)=>`<option value="${i}">Question ${i+1}</option>`).join('');$('fg-answer').innerHTML='<option value="">Select a functional group</option>'+Object.entries(info).sort((a,b)=>a[1][0].localeCompare(b[1][0])).map(([key,value])=>`<option value="${key}">${value[0]}</option>`).join('');$('fg-question').onchange=e=>begin(+e.target.value);document.querySelectorAll('[data-fg-mode]').forEach(b=>b.onclick=()=>choose(b.dataset.fgMode));$('fg-previous').onclick=()=>begin(index-1);$('fg-next').onclick=()=>begin(index+1);$('fg-check').onclick=check;$('fg-hint').onclick=()=>message('Hint: '+info[members(current()).type][1]);function select(e){const hit=e.target.closest('[data-fg-kind]');if(!hit||solved.has(key()))return;selection={kind:hit.dataset.fgKind,id:hit.dataset.fgId};$('fg-board').innerHTML=markup(current());message('Selection made. Select Check Answer to test it.');}$('fg-board').addEventListener('click',select);$('fg-board').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(e);}});begin();if(globalThis.__FG_TEST__)globalThis.functionalGroupApi={begin,choose,current,check,grade,members,markup};})();
